    ["04-47"] = {steps={[1]={npc="Аратандис Серебряное Небо", tgt="Аратандис Серебряное Небо"}, [2]={npc="Гразл", tgt="Гразл"}, [3]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [4]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [5]={npc="Тарун Красное Перо", tgt="Тарун Красное Перо", tag="Необязательно"}, [6]={hint="Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 6 воинов, 6 землепроходцев и 6 садовников из племени Мертвого Леса. Выполнив поручение, возвращайтесь в южную часть Оскверненного леса к Изумрудному святилищу."}, [7]={npc="Гразл", tgt="Гразл"}, [8]={npc="Гразл", tgt="Гразл"}, [9]={hint="Убейте 11 скверноподданных, 9 тенеловов, 9 разбойников из племени Нефритового Пламени и Ксаватраса. Возвращайтесь к Эридане Грусти Ветра в Оскверненный лес по выполнении задания."}, [10]={hint="Отправляйтесь в Джеденар и убейте 4 джеденарских гончих, 4 джеденарских стражей, 6 джеденарских адептов и 6 джеденарских сектантов, затем возвращайтесь к Грете Заиндевевшее Копыто в Оскверненный лес."}, [11]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [12]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [13]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [14]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [15]={hint="Возьмите пустую флягу и наполните ее водой из лунного колодца, что находится в центре Джеденара. Возвращайтесь к Грете Замшелому Копыту в Оскверненный лес."}, [17]={hint="Найдите и уничтожьте 2 энтропических зверей и 2 энтропических ужасов при обследовании долины Рваных Ран. После проверьте, по-прежнему ли заполнены кратеры оскверненной водой. Затем возвращайтесь к Таруну Красному Перу в Оскверненный лес.", tag="Необязательно"}, [18]={hint="Эридана Грусть Ветра из Оскверненного леса просит вас убить 8 призывателей огня, 8 предателей и 8 плутов из племени Нефритового огня, а также Ксаварика. По выполнении задания возвращайтесь к Эридане."}, [19]={npc="Флейта Ксаварика", npcObj=true}, [20]={hint="Принесите флейту Ксаварика и 5 образцов уз Скверны нефритового огня Эридане Грусти Ветра в южную часть Оскверненного леса."}, [21]={hint="Принесите 15 кровавых янтарей Аратандис Серебряному Небу в Оскверненный лес."}, [22]={}, [23]={npc="Нафиэн", tgt="Нафиэн"}, [24]={npc="Нафиэн", tgt="Нафиэн", tag="Требуется внутриигровая проверка"}, [25]={hint="Нафиэн просит вас убить 6 дозорных, 6 мстителей и 6 шаманов из племени Мертвого Леса. По выполнении возвращайтесь на север Оскверненного леса ко входу в крепость Древобрюхов.", tag="Требуется внутриигровая проверка"}, [26]={npc="Нафиэн", tgt="Нафиэн", tag="Требуется внутриигровая проверка"}, [27]={}, [28]={npc="Сальфа", tgt="Сальфа", tag="Требуется внутриигровая проверка"}, [29]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [30]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [31]={npc="Мегги Молот-Шмолот", tgt="Мегги Молот-Шмолот"}, [32]={npc="Джессика Редпат", tgt="Джессика Редпат"}, [33]={nodeA="{a:2255}"}}},
